import numpy as np

def get_max_s2(n):
    best_s2 = 0
    # x_i is either 2, 0, or c
    # k are 2, m are c, n-k-m are 0
    for k in range(n + 1):
        for m in range(1, n - k + 1):
            # 8k + m*c^3 = 0  => c = (-8k/m)^(1/3)
            c = (-8 * k / m)**(1/3) if k*m != 0 else 0
            if k == 0:
                # If k=0, then m*c^3 = 0 => c=0. S2 = 0.
                s2 = 0
            else:
                # S2 = (1/n) * (k*2^2 + m*c^2)
                s2 = (1/n) * (4*k + m * (abs(-8 * k / m)**(2/3)))
            best_s2 = max(best_s2, s2)
    return best_s2

for n in range(1, 21):
    print(f"n={n}, max_s2={get_max_s2(n):.4f}")
